#!/usr/bin/env python3
"""jsonschema-cli reimplementation."""
from __future__ import annotations

import json
import os
import re
import sys
from typing import Any, Callable, Iterable, List, Optional, Tuple


VERSION = "0.41.0"


HELP_TEXT = (
    "Usage: executable [OPTIONS] [SCHEMA]\n"
    "\n"
    "Arguments:\n"
    "  [SCHEMA]  The JSON Schema to validate with (i.e. schema.json)\n"
    "\n"
    "Options:\n"
    "  -i, --instance <INSTANCES>       A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)\n"
    "  -d, --draft <DRAFT>              Enforce a specific JSON Schema draft [possible values: 4, 6, 7, 2019, 2020]\n"
    "      --assert-format              Turn ON format validation\n"
    "      --no-assert-format           Turn OFF format validation\n"
    "      --output <OUTPUT>            Select output style: text (default), flag, list, hierarchical [default: text] [possible values: text, flag, list, hierarchical]\n"
    "  -v, --version                    Show program's version number and exit\n"
    "      --errors-only                Only show validation errors\n"
    "      --connect-timeout <SECONDS>  Timeout for establishing connections (in seconds)\n"
    "      --timeout <SECONDS>          Total timeout for HTTP requests (in seconds)\n"
    "  -k, --insecure                   Skip TLS certificate verification (dangerous!)\n"
    "      --cacert <FILE>              Path to a custom CA certificate file (PEM format)\n"
    "  -h, --help                       Print help\n"
)


DRAFT_VALUES = ["4", "6", "7", "2019", "2020"]
OUTPUT_VALUES = ["text", "flag", "list", "hierarchical"]


class CliError(Exception):
    def __init__(self, message: str, usage_suffix: str = ""):
        super().__init__(message)
        self.message = message
        self.usage_suffix = usage_suffix


def usage_line(suffix: str = "") -> str:
    tail = " [OPTIONS] [SCHEMA]" if not suffix else suffix
    return f"Usage: executable{tail}"


def die_cli(message: str, usage_suffix: str = "") -> None:
    sys.stderr.write(f"error: {message}\n\n")
    sys.stderr.write(usage_line(usage_suffix) + "\n\n")
    sys.stderr.write("For more information, try '--help'.\n")
    sys.exit(2)


class Args:
    def __init__(self) -> None:
        self.schema: Optional[str] = None
        self.instances: List[str] = []
        self.draft: Optional[str] = None
        self.assert_format: Optional[bool] = None
        self.output: str = "text"
        self.errors_only: bool = False
        self.connect_timeout: Optional[str] = None
        self.timeout: Optional[str] = None
        self.insecure: bool = False
        self.cacert: Optional[str] = None
        self.explicit_flags: List[str] = []


def parse_args(argv: List[str]) -> Args:
    args = Args()
    i = 0
    positional: List[str] = []
    n = len(argv)
    # Definitions for known options requiring a value
    value_opts_long = {
        "--instance": "instances",
        "--draft": "draft",
        "--output": "output",
        "--connect-timeout": "connect_timeout",
        "--timeout": "timeout",
        "--cacert": "cacert",
    }
    value_opts_short = {
        "-i": ("--instance", "instances"),
        "-d": ("--draft", "draft"),
    }
    bool_opts = {
        "--assert-format": ("assert_format", True),
        "--no-assert-format": ("assert_format", False),
        "--errors-only": ("errors_only", True),
        "--insecure": ("insecure", True),
        "-k": ("insecure", True),
    }
    explicit_usage_pieces: List[Tuple[int, str]] = []

    def record_usage(name: str, metavar: str, priority: int) -> None:
        # Order of clap usage: --output, --instance typically
        explicit_usage_pieces.append((priority, f"{name} <{metavar}>"))

    def usage_suffix() -> str:
        pieces = [p for _, p in sorted(explicit_usage_pieces, key=lambda x: x[0])]
        if pieces:
            return " " + " ".join(pieces) + " <SCHEMA>"
        return ""

    while i < n:
        a = argv[i]
        if a == "--":
            i += 1
            positional.extend(argv[i:])
            break
        if a in ("-h", "--help"):
            sys.stdout.write(HELP_TEXT)
            sys.exit(0)
        if a in ("-v", "--version"):
            sys.stdout.write(f"Version: {VERSION}\n")
            sys.exit(0)
        # Handle --opt=value form
        eq_val: Optional[str] = None
        if a.startswith("--") and "=" in a:
            key, eq_val = a.split("=", 1)
        else:
            key = a
        if key in value_opts_long:
            attr = value_opts_long[key]
            metavar = {
                "instances": "INSTANCES",
                "draft": "DRAFT",
                "output": "OUTPUT",
                "connect_timeout": "SECONDS",
                "timeout": "SECONDS",
                "cacert": "FILE",
            }[attr]
            if eq_val is not None:
                val = eq_val
            else:
                if i + 1 >= n:
                    priority = 0
                    if key == "--output":
                        priority = 0
                    elif key == "--instance":
                        priority = 1
                    record_usage(key, metavar, priority)
                    die_cli(
                        f"a value is required for '{key} <{metavar}>' but none was supplied"
                        + (possible_values_hint(attr)),
                        usage_suffix(),
                    )
                i += 1
                val = argv[i]
            # Validate values for draft / output
            if attr == "draft":
                if val not in DRAFT_VALUES:
                    die_cli(
                        f"invalid value '{val}' for '--draft <DRAFT>'\n"
                        f"  [possible values: 4, 6, 7, 2019, 2020]",
                        "",
                    )
                args.draft = val
            elif attr == "output":
                if val not in OUTPUT_VALUES:
                    die_cli(
                        f"invalid value '{val}' for '--output <OUTPUT>'\n"
                        f"  [possible values: text, flag, list, hierarchical]",
                        "",
                    )
                args.output = val
                record_usage("--output", "OUTPUT", 0)
            elif attr == "instances":
                args.instances.append(val)
                record_usage("--instance", "INSTANCES", 1)
            elif attr == "connect_timeout":
                args.connect_timeout = val
            elif attr == "timeout":
                args.timeout = val
            elif attr == "cacert":
                args.cacert = val
            i += 1
            continue
        if key in value_opts_short and eq_val is None:
            long, attr = value_opts_short[key]
            metavar = {"instances": "INSTANCES", "draft": "DRAFT"}[attr]
            if i + 1 >= n:
                priority = 1 if attr == "instances" else 0
                record_usage(long, metavar, priority)
                die_cli(
                    f"a value is required for '{long} <{metavar}>' but none was supplied"
                    + (possible_values_hint(attr)),
                    usage_suffix(),
                )
            i += 1
            val = argv[i]
            if attr == "draft":
                if val not in DRAFT_VALUES:
                    die_cli(
                        f"invalid value '{val}' for '--draft <DRAFT>'\n"
                        f"  [possible values: 4, 6, 7, 2019, 2020]",
                        "",
                    )
                args.draft = val
            elif attr == "instances":
                args.instances.append(val)
                record_usage("--instance", "INSTANCES", 1)
            i += 1
            continue
        if a in bool_opts and eq_val is None:
            attr, val = bool_opts[a]
            setattr(args, attr, val)
            i += 1
            continue
        if a.startswith("-") and a != "-":
            # Unknown option
            hint = ""
            if a.startswith("--"):
                hint = f"\n\n  tip: to pass '{a}' as a value, use '-- {a}'"
            die_cli(f"unexpected argument '{a}' found{hint}", usage_suffix())
        # positional
        positional.append(a)
        i += 1

    if len(positional) > 1:
        die_cli(f"unexpected argument '{positional[1]}' found", usage_suffix())
    if positional:
        args.schema = positional[0]
    else:
        # SCHEMA is required
        sys.stderr.write(
            "error: the following required arguments were not provided:\n"
            "  <SCHEMA>\n\n"
        )
        pieces = [p for _, p in sorted(explicit_usage_pieces, key=lambda x: x[0])]
        if pieces:
            sys.stderr.write("Usage: executable " + " ".join(pieces) + " <SCHEMA>\n\n")
        else:
            sys.stderr.write("Usage: executable <SCHEMA>\n\n")
        sys.stderr.write("For more information, try '--help'.\n")
        sys.exit(2)
    return args


def possible_values_hint(attr: str) -> str:
    if attr == "draft":
        return "\n  [possible values: 4, 6, 7, 2019, 2020]"
    if attr == "output":
        return "\n  [possible values: text, flag, list, hierarchical]"
    return ""


# ---------- JSON helpers ----------

def canon_json(obj: Any) -> str:
    """JSON encoding matching serde_json: compact, sorted? No, serde preserves order.
    However for error messages some items (like instance) are compact, order-preserving.
    For uniqueness comparisons we need canonical form."""
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"))


def canon_sorted(obj: Any) -> str:
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"), sort_keys=True)


def format_value(value: Any) -> str:
    """Format a value for user-facing messages (e.g., `"str"`, `5`, `[1,2,3]`)."""
    return canon_json(value)


def json_equal(a: Any, b: Any) -> bool:
    """JSON-equal: numbers 1 == 1.0, but true != 1."""
    if isinstance(a, bool) or isinstance(b, bool):
        if isinstance(a, bool) and isinstance(b, bool):
            return a == b
        return False
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return float(a) == float(b)
    if type(a) is not type(b):
        return False
    if isinstance(a, list):
        if len(a) != len(b):
            return False
        return all(json_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(json_equal(a[k], b[k]) for k in a)
    return a == b


# ---------- Numeric helpers ----------

def is_number(v: Any) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def is_integer(v: Any) -> bool:
    if isinstance(v, bool):
        return False
    if isinstance(v, int):
        return True
    if isinstance(v, float):
        return v.is_integer()
    return False


def type_of(v: Any) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, int):
        return "integer"
    if isinstance(v, float):
        return "integer" if v.is_integer() else "number"
    if isinstance(v, str):
        return "string"
    if isinstance(v, list):
        return "array"
    if isinstance(v, dict):
        return "object"
    return "unknown"


# ---------- Validation errors ----------

class ValidationError(Exception):
    def __init__(self, message: str, keyword: str, evaluation_path: str, instance_path: str):
        self.message = message
        self.keyword = keyword
        self.evaluation_path = evaluation_path
        self.instance_path = instance_path


def escape_pointer(segment: str) -> str:
    return segment.replace("~", "~0").replace("/", "~1")


# ---------- Schema Draft detection ----------

def detect_draft(schema: Any, forced: Optional[str]) -> str:
    if forced is not None:
        return {"4": "4", "6": "6", "7": "7", "2019": "2019", "2020": "2020"}[forced]
    if isinstance(schema, dict):
        sch = schema.get("$schema")
        if isinstance(sch, str):
            if "draft-04" in sch:
                return "4"
            if "draft-06" in sch:
                return "6"
            if "draft-07" in sch:
                return "7"
            if "2019-09" in sch:
                return "2019"
            if "2020-12" in sch:
                return "2020"
    return "2020"


# ---------- The validator ----------

class Validator:
    def __init__(self, root: Any, draft: str, assert_format: bool):
        self.root = root
        self.draft = draft
        self.assert_format = assert_format

    def resolve_ref(self, ref: str) -> Any:
        if not ref.startswith("#"):
            return None
        frag = ref[1:]
        if frag.startswith("/"):
            parts = frag.split("/")[1:]
        elif frag == "":
            return self.root
        else:
            return None
        node = self.root
        for p in parts:
            p = p.replace("~1", "/").replace("~0", "~")
            try:
                # url-decode percent sequences
                p = re.sub(r"%([0-9A-Fa-f]{2})", lambda m: chr(int(m.group(1), 16)), p)
            except Exception:
                pass
            if isinstance(node, dict) and p in node:
                node = node[p]
            elif isinstance(node, list):
                try:
                    node = node[int(p)]
                except Exception:
                    return None
            else:
                return None
        return node

    def validate(
        self,
        schema: Any,
        instance: Any,
        schema_path: str,
        inst_path: str,
        errors: List[ValidationError],
    ) -> None:
        if schema is True or schema == {}:
            return
        if schema is False:
            errors.append(ValidationError(
                f"False schema does not allow {format_value(instance)}",
                "falseSchema", schema_path, inst_path,
            ))
            return
        if not isinstance(schema, dict):
            return
        # $ref
        if "$ref" in schema and isinstance(schema["$ref"], str):
            target = self.resolve_ref(schema["$ref"])
            if target is not None:
                self.validate(target, instance, schema_path + "/$ref", inst_path, errors)
                # draft 2019+ allows sibling keywords; draft 7 ignores them
                if self.draft in ("4", "6", "7"):
                    return
        # type
        if "type" in schema:
            t = schema["type"]
            ts = t if isinstance(t, list) else [t]
            if not any(self._type_matches(ti, instance) for ti in ts):
                if isinstance(t, list):
                    sorted_ts = ", ".join(f'"{x}"' for x in sorted(ts))
                    errors.append(ValidationError(
                        f"{format_value(instance)} is not of types {sorted_ts}",
                        "type", schema_path + "/type", inst_path,
                    ))
                else:
                    errors.append(ValidationError(
                        f"{format_value(instance)} is not of type \"{t}\"",
                        "type", schema_path + "/type", inst_path,
                    ))

        # enum
        if "enum" in schema:
            enum_values = schema["enum"]
            if not any(json_equal(instance, ev) for ev in enum_values):
                if len(enum_values) == 1:
                    msg = f"{format_value(instance)} is not one of {format_value(enum_values[0])}"
                elif len(enum_values) == 2:
                    msg = (
                        f"{format_value(instance)} is not one of "
                        f"{format_value(enum_values[0])} or {format_value(enum_values[1])}"
                    )
                else:
                    rest = len(enum_values) - 2
                    msg = (
                        f"{format_value(instance)} is not one of "
                        f"{format_value(enum_values[0])}, {format_value(enum_values[1])} or {rest} other candidates"
                    )
                errors.append(ValidationError(
                    msg, "enum", schema_path + "/enum", inst_path,
                ))

        # const
        if "const" in schema:
            if not json_equal(instance, schema["const"]):
                errors.append(ValidationError(
                    f"{format_value(schema['const'])} was expected",
                    "const", schema_path + "/const", inst_path,
                ))

        # allOf
        if "allOf" in schema and isinstance(schema["allOf"], list):
            for i, sub in enumerate(schema["allOf"]):
                self.validate(sub, instance, f"{schema_path}/allOf/{i}", inst_path, errors)
        # anyOf
        if "anyOf" in schema and isinstance(schema["anyOf"], list):
            any_ok = False
            for sub in schema["anyOf"]:
                sub_errors: List[ValidationError] = []
                self.validate(sub, instance, "", inst_path, sub_errors)
                if not sub_errors:
                    any_ok = True
                    break
            if not any_ok:
                errors.append(ValidationError(
                    f"{format_value(instance)} is not valid under any of the schemas listed in the 'anyOf' keyword",
                    "anyOf", schema_path + "/anyOf", inst_path,
                ))
        # oneOf
        if "oneOf" in schema and isinstance(schema["oneOf"], list):
            ok_count = 0
            for sub in schema["oneOf"]:
                sub_errors: List[ValidationError] = []
                self.validate(sub, instance, "", inst_path, sub_errors)
                if not sub_errors:
                    ok_count += 1
                    if ok_count > 1:
                        break
            if ok_count == 0:
                errors.append(ValidationError(
                    f"{format_value(instance)} is not valid under any of the schemas listed in the 'oneOf' keyword",
                    "oneOf", schema_path + "/oneOf", inst_path,
                ))
            elif ok_count > 1:
                errors.append(ValidationError(
                    f"{format_value(instance)} is valid under more than one of the schemas listed in the 'oneOf' keyword",
                    "oneOf", schema_path + "/oneOf", inst_path,
                ))
        # not
        if "not" in schema:
            sub_errors: List[ValidationError] = []
            self.validate(schema["not"], instance, "", inst_path, sub_errors)
            if not sub_errors:
                errors.append(ValidationError(
                    f"{format_value(schema['not'])} is not allowed for {format_value(instance)}",
                    "not", schema_path + "/not", inst_path,
                ))

        # numeric constraints
        if is_number(instance):
            if "minimum" in schema:
                m = schema["minimum"]
                if is_number(m):
                    if instance < m:
                        errors.append(ValidationError(
                            f"{format_value(instance)} is less than the minimum of {format_value(m)}",
                            "minimum", schema_path + "/minimum", inst_path,
                        ))
            if "maximum" in schema:
                m = schema["maximum"]
                if is_number(m):
                    if instance > m:
                        errors.append(ValidationError(
                            f"{format_value(instance)} is greater than the maximum of {format_value(m)}",
                            "maximum", schema_path + "/maximum", inst_path,
                        ))
            if "exclusiveMinimum" in schema:
                m = schema["exclusiveMinimum"]
                if is_number(m):
                    if instance <= m:
                        errors.append(ValidationError(
                            f"{format_value(instance)} is less than or equal to the minimum of {format_value(m)}",
                            "exclusiveMinimum", schema_path + "/exclusiveMinimum", inst_path,
                        ))
            if "exclusiveMaximum" in schema:
                m = schema["exclusiveMaximum"]
                if is_number(m):
                    if instance >= m:
                        errors.append(ValidationError(
                            f"{format_value(instance)} is greater than or equal to the maximum of {format_value(m)}",
                            "exclusiveMaximum", schema_path + "/exclusiveMaximum", inst_path,
                        ))
            if "multipleOf" in schema:
                mo = schema["multipleOf"]
                if is_number(mo) and mo > 0:
                    q = instance / mo
                    if abs(q - round(q)) > 1e-12:
                        errors.append(ValidationError(
                            f"{format_value(instance)} is not a multiple of {format_value(mo)}",
                            "multipleOf", schema_path + "/multipleOf", inst_path,
                        ))

        # string constraints
        if isinstance(instance, str):
            if "minLength" in schema and isinstance(schema["minLength"], int):
                if len(instance) < schema["minLength"]:
                    errors.append(ValidationError(
                        f"{format_value(instance)} is shorter than {schema['minLength']} characters",
                        "minLength", schema_path + "/minLength", inst_path,
                    ))
            if "maxLength" in schema and isinstance(schema["maxLength"], int):
                if len(instance) > schema["maxLength"]:
                    errors.append(ValidationError(
                        f"{format_value(instance)} is longer than {schema['maxLength']} characters",
                        "maxLength", schema_path + "/maxLength", inst_path,
                    ))
            if "pattern" in schema and isinstance(schema["pattern"], str):
                try:
                    if not re.search(schema["pattern"], instance):
                        errors.append(ValidationError(
                            f"{format_value(instance)} does not match \"{schema['pattern']}\"",
                            "pattern", schema_path + "/pattern", inst_path,
                        ))
                except re.error:
                    pass
            if self.assert_format and "format" in schema and isinstance(schema["format"], str):
                if not check_format(schema["format"], instance):
                    errors.append(ValidationError(
                        f"{format_value(instance)} is not a \"{schema['format']}\"",
                        "format", schema_path + "/format", inst_path,
                    ))

        # array constraints
        if isinstance(instance, list):
            if "minItems" in schema and isinstance(schema["minItems"], int):
                if len(instance) < schema["minItems"]:
                    word = "item" if schema["minItems"] == 1 else "items"
                    errors.append(ValidationError(
                        f"{format_value(instance)} has less than {schema['minItems']} {word}",
                        "minItems", schema_path + "/minItems", inst_path,
                    ))
            if "maxItems" in schema and isinstance(schema["maxItems"], int):
                if len(instance) > schema["maxItems"]:
                    word = "item" if schema["maxItems"] == 1 else "items"
                    errors.append(ValidationError(
                        f"{format_value(instance)} has more than {schema['maxItems']} {word}",
                        "maxItems", schema_path + "/maxItems", inst_path,
                    ))
            if schema.get("uniqueItems") is True:
                seen: List[str] = []
                dup = False
                for e in instance:
                    k = canon_sorted(e) + "|" + type_of(e)
                    if k in seen:
                        dup = True
                        break
                    seen.append(k)
                if dup:
                    errors.append(ValidationError(
                        f"{format_value(instance)} has non-unique elements",
                        "uniqueItems", schema_path + "/uniqueItems", inst_path,
                    ))
            if "items" in schema:
                items = schema["items"]
                if isinstance(items, list):
                    # Only drafts <= 2019 support this.
                    for idx, el in enumerate(instance):
                        if idx < len(items):
                            self.validate(items[idx], el, f"{schema_path}/items/{idx}",
                                          f"{inst_path}/{idx}", errors)
                    if "additionalItems" in schema:
                        ai = schema["additionalItems"]
                        for idx, el in enumerate(instance):
                            if idx >= len(items):
                                self.validate(ai, el, f"{schema_path}/additionalItems",
                                              f"{inst_path}/{idx}", errors)
                else:
                    start = 0
                    if "prefixItems" in schema and isinstance(schema["prefixItems"], list):
                        start = len(schema["prefixItems"])
                    for idx, el in enumerate(instance):
                        if idx < start:
                            continue
                        self.validate(items, el, f"{schema_path}/items",
                                      f"{inst_path}/{idx}", errors)
            if "prefixItems" in schema and isinstance(schema["prefixItems"], list):
                for idx, el in enumerate(instance):
                    if idx < len(schema["prefixItems"]):
                        self.validate(schema["prefixItems"][idx], el,
                                      f"{schema_path}/prefixItems/{idx}",
                                      f"{inst_path}/{idx}", errors)
            if "contains" in schema:
                ok = False
                for el in instance:
                    sub_errors: List[ValidationError] = []
                    self.validate(schema["contains"], el, "", inst_path, sub_errors)
                    if not sub_errors:
                        ok = True
                        break
                if not ok:
                    errors.append(ValidationError(
                        f"None of {format_value(instance)} are valid under the given schema",
                        "contains", schema_path + "/contains", inst_path,
                    ))

        # object constraints
        if isinstance(instance, dict):
            if "required" in schema and isinstance(schema["required"], list):
                for r in schema["required"]:
                    if r not in instance:
                        errors.append(ValidationError(
                            f"\"{r}\" is a required property",
                            "required", schema_path + "/required", inst_path,
                        ))
            if "minProperties" in schema and isinstance(schema["minProperties"], int):
                if len(instance) < schema["minProperties"]:
                    word = "property" if schema["minProperties"] == 1 else "properties"
                    errors.append(ValidationError(
                        f"{format_value(instance)} has less than {schema['minProperties']} {word}",
                        "minProperties", schema_path + "/minProperties", inst_path,
                    ))
            if "maxProperties" in schema and isinstance(schema["maxProperties"], int):
                if len(instance) > schema["maxProperties"]:
                    word = "property" if schema["maxProperties"] == 1 else "properties"
                    errors.append(ValidationError(
                        f"{format_value(instance)} has more than {schema['maxProperties']} {word}",
                        "maxProperties", schema_path + "/maxProperties", inst_path,
                    ))
            props = schema.get("properties", {}) if isinstance(schema.get("properties"), dict) else {}
            pattern_props = schema.get("patternProperties", {}) if isinstance(schema.get("patternProperties"), dict) else {}
            ap = schema.get("additionalProperties", None)
            if props:
                for pname, psub in props.items():
                    if pname in instance:
                        self.validate(psub, instance[pname],
                                      f"{schema_path}/properties/{escape_pointer(pname)}",
                                      f"{inst_path}/{escape_pointer(pname)}", errors)
            if pattern_props:
                for pat, psub in pattern_props.items():
                    try:
                        pat_c = re.compile(pat)
                    except re.error:
                        continue
                    for k, v in instance.items():
                        if pat_c.search(k):
                            self.validate(psub, v,
                                          f"{schema_path}/patternProperties/{escape_pointer(pat)}",
                                          f"{inst_path}/{escape_pointer(k)}", errors)
            if ap is not None and ap is not True:
                unmatched = []
                for k in instance:
                    if k in props:
                        continue
                    matched = False
                    for pat in pattern_props:
                        try:
                            if re.compile(pat).search(k):
                                matched = True
                                break
                        except re.error:
                            pass
                    if not matched:
                        unmatched.append(k)
                if ap is False:
                    if unmatched:
                        extras = ", ".join(f"'{u}'" for u in unmatched)
                        were = "were" if len(unmatched) != 1 else "was"
                        errors.append(ValidationError(
                            f"Additional properties are not allowed ({extras} {were} unexpected)",
                            "additionalProperties",
                            schema_path + "/additionalProperties", inst_path,
                        ))
                elif isinstance(ap, dict):
                    for u in unmatched:
                        self.validate(ap, instance[u],
                                      schema_path + "/additionalProperties",
                                      f"{inst_path}/{escape_pointer(u)}", errors)
            if "dependencies" in schema and isinstance(schema["dependencies"], dict):
                for k, v in schema["dependencies"].items():
                    if k in instance:
                        if isinstance(v, list):
                            for r in v:
                                if r not in instance:
                                    errors.append(ValidationError(
                                        f"\"{r}\" is a required property",
                                        "dependencies",
                                        f"{schema_path}/dependencies/{escape_pointer(k)}",
                                        inst_path,
                                    ))
                        else:
                            self.validate(v, instance,
                                          f"{schema_path}/dependencies/{escape_pointer(k)}",
                                          inst_path, errors)
            if "dependentRequired" in schema and isinstance(schema["dependentRequired"], dict):
                for k, v in schema["dependentRequired"].items():
                    if k in instance and isinstance(v, list):
                        for r in v:
                            if r not in instance:
                                errors.append(ValidationError(
                                    f"\"{r}\" is a required property",
                                    "dependentRequired",
                                    f"{schema_path}/dependentRequired/{escape_pointer(k)}",
                                    inst_path,
                                ))
            if "dependentSchemas" in schema and isinstance(schema["dependentSchemas"], dict):
                for k, v in schema["dependentSchemas"].items():
                    if k in instance:
                        self.validate(v, instance,
                                      f"{schema_path}/dependentSchemas/{escape_pointer(k)}",
                                      inst_path, errors)
            if "propertyNames" in schema:
                for k in instance:
                    self.validate(schema["propertyNames"], k,
                                  schema_path + "/propertyNames", inst_path, errors)
            if "if" in schema:
                sub_errors: List[ValidationError] = []
                self.validate(schema["if"], instance, "", inst_path, sub_errors)
                if not sub_errors and "then" in schema:
                    self.validate(schema["then"], instance,
                                  schema_path + "/then", inst_path, errors)
                elif sub_errors and "else" in schema:
                    self.validate(schema["else"], instance,
                                  schema_path + "/else", inst_path, errors)

    def _type_matches(self, t: str, instance: Any) -> bool:
        if t == "null":
            return instance is None
        if t == "boolean":
            return isinstance(instance, bool)
        if t == "integer":
            return is_integer(instance)
        if t == "number":
            return is_number(instance)
        if t == "string":
            return isinstance(instance, str)
        if t == "array":
            return isinstance(instance, list)
        if t == "object":
            return isinstance(instance, dict)
        return False


# ---------- Format check stub ----------

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
IPV4_RE = re.compile(r"^(\d{1,3}\.){3}\d{1,3}$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
TIME_RE = re.compile(r"^\d{2}:\d{2}:\d{2}")
DATE_TIME_RE = re.compile(r"^\d{4}-\d{2}-\d{2}[Tt]\d{2}:\d{2}:\d{2}")
URI_RE = re.compile(r"^[A-Za-z][A-Za-z0-9+\-.]*:.+")


def check_format(fmt: str, value: str) -> bool:
    if fmt == "email":
        return EMAIL_RE.match(value) is not None
    if fmt == "ipv4":
        if not IPV4_RE.match(value):
            return False
        return all(0 <= int(p) <= 255 for p in value.split("."))
    if fmt == "date":
        return DATE_RE.match(value) is not None
    if fmt == "time":
        return TIME_RE.match(value) is not None
    if fmt == "date-time":
        return DATE_TIME_RE.match(value) is not None
    if fmt == "uri":
        return URI_RE.match(value) is not None
    if fmt == "uuid":
        return re.match(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$", value) is not None
    # Unknown formats pass by default
    return True


# ---------- Meta-schema style validation ----------

ALL_TYPES = {"null", "boolean", "integer", "number", "string", "array", "object"}


def validate_schema(schema: Any) -> Optional[str]:
    """Validate that a schema is well-formed; return an error message or None."""
    if schema is True or schema is False:
        return None
    if not isinstance(schema, dict):
        return f"{format_value(schema)} is not of types \"boolean\", \"object\""
    # Check type keyword
    if "type" in schema:
        t = schema["type"]
        if isinstance(t, str):
            if t not in ALL_TYPES:
                return (
                    f"{format_value(t)} is not valid under any of the schemas listed in the 'anyOf' keyword"
                )
        elif isinstance(t, list):
            for item in t:
                if not isinstance(item, str) or item not in ALL_TYPES:
                    return (
                        f"{format_value(t)} is not valid under any of the schemas listed in the 'anyOf' keyword"
                    )
        else:
            return (
                f"{format_value(t)} is not valid under any of the schemas listed in the 'anyOf' keyword"
            )
    # Check minLength / maxLength / minItems etc. types
    int_keys = [
        "minLength", "maxLength", "minItems", "maxItems",
        "minProperties", "maxProperties",
    ]
    for k in int_keys:
        if k in schema:
            v = schema[k]
            if not (isinstance(v, int) and not isinstance(v, bool) and v >= 0):
                return f"{format_value(v)} is not of type \"integer\""
    # `items` cannot be a list for draft 2020 (but we don't know draft here yet)
    # Recurse into subschemas
    for key in ("allOf", "anyOf", "oneOf"):
        if key in schema and isinstance(schema[key], list):
            for sub in schema[key]:
                err = validate_schema(sub)
                if err:
                    return err
    if "not" in schema:
        err = validate_schema(schema["not"])
        if err:
            return err
    if "properties" in schema and isinstance(schema["properties"], dict):
        for v in schema["properties"].values():
            err = validate_schema(v)
            if err:
                return err
    if "items" in schema:
        # For draft 2020-12, items must not be array, but we don't track that here.
        if isinstance(schema["items"], list):
            for sub in schema["items"]:
                err = validate_schema(sub)
                if err:
                    return err
        else:
            err = validate_schema(schema["items"])
            if err:
                return err
    return None


# ---------- Output formatting ----------

def format_text(
    instance_path: str,
    errors: List[ValidationError],
    errors_only: bool,
) -> Optional[str]:
    if not errors:
        if errors_only:
            return None
        return f"{instance_path} - VALID"
    lines = [f"{instance_path} - INVALID. Errors:"]
    # Order errors by insertion (already inserted in order they are encountered)
    for i, e in enumerate(errors, 1):
        lines.append(f"{i}. {e.message}")
    return "\n".join(lines)


def make_schema_location(schema_path_abs: str, ptr: str) -> str:
    return f"file://{schema_path_abs}#{ptr}"


def format_flag(schema: str, instance: str, output: str, valid: bool) -> str:
    payload = {"valid": valid}
    doc = {"instance": instance, "output": output, "payload": payload, "schema": schema}
    return canon_sorted(doc)


# ---------- Main ----------

def load_json_file(path: str) -> Any:
    with open(path, "rb") as f:
        data = f.read()
    return json.loads(data)


def format_io_error(exc: Exception) -> str:
    if isinstance(exc, FileNotFoundError):
        return "No such file or directory (os error 2)"
    if isinstance(exc, IsADirectoryError):
        return "Is a directory (os error 21)"
    if isinstance(exc, PermissionError):
        return "Permission denied (os error 13)"
    return str(exc)


def format_json_error(exc: json.JSONDecodeError) -> str:
    msg = exc.msg
    line = exc.lineno
    col = exc.colno
    # Map Python's JSON error messages to serde-style
    if "Expecting value" in msg:
        return f"expected ident at line {line} column {col}"
    if "Extra data" in msg:
        return f"trailing characters at line {line} column {col}"
    if "Expecting property name" in msg:
        return f"expected property name at line {line} column {col}"
    if "Expecting ',' delimiter" in msg:
        return f"expected `,` or `}}` at line {line} column {col}"
    if "Unterminated string" in msg:
        return f"EOF while parsing a string at line {line} column {col}"
    return f"{msg} at line {line} column {col}"


def main(argv: Optional[List[str]] = None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    args = parse_args(argv)

    # Load the schema
    assert args.schema is not None
    schema_path = args.schema
    try:
        schema = load_json_file(schema_path)
    except json.JSONDecodeError as e:
        sys.stderr.write(f"Error: {format_json_error(e)}\n")
        return 1
    except OSError as e:
        sys.stderr.write(f"Error: {format_io_error(e)}\n")
        return 1

    draft = detect_draft(schema, args.draft)
    assert_format = args.assert_format if args.assert_format is not None else False
    # For drafts < 2019 format assertion is on by default; but we follow
    # the newer default (off).

    schema_err = validate_schema(schema)
    if schema_err and not args.instances:
        print(f"Schema is invalid. Error: {schema_err}")
        return 1

    if not args.instances:
        print("Schema is valid")
        return 0

    if schema_err:
        # When there are instances and schema is invalid, still report once.
        print(f"Schema is invalid. Error: {schema_err}")
        return 1

    validator = Validator(schema, draft, assert_format)
    overall_exit = 0
    schema_abs = os.path.abspath(schema_path)

    for inst_path in args.instances:
        try:
            instance = load_json_file(inst_path)
        except json.JSONDecodeError as e:
            sys.stderr.write(f"Error: {format_json_error(e)}\n")
            return 1
        except OSError as e:
            sys.stderr.write(f"Error: {format_io_error(e)}\n")
            return 1
        errors: List[ValidationError] = []
        validator.validate(schema, instance, "", "", errors)
        is_valid = not errors
        if not is_valid:
            overall_exit = 1
        if args.output == "text":
            out = format_text(inst_path, errors, args.errors_only)
            if out is not None:
                print(out)
        elif args.output == "flag":
            doc = {
                "instance": inst_path,
                "output": "flag",
                "payload": {"valid": is_valid},
                "schema": schema_path,
            }
            print(canon_sorted(doc))
        elif args.output == "list":
            details = build_list_details(schema, instance, schema_abs, validator)
            payload = {"details": details, "valid": is_valid}
            doc = {
                "instance": inst_path,
                "output": "list",
                "payload": payload,
                "schema": schema_path,
            }
            print(canon_sorted(doc))
        elif args.output == "hierarchical":
            payload = build_hierarchical(schema, instance, schema_abs, validator, "", "", "")
            doc = {
                "instance": inst_path,
                "output": "hierarchical",
                "payload": payload,
                "schema": schema_path,
            }
            print(canon_sorted(doc))
    return overall_exit


def build_list_details(schema: Any, instance: Any, schema_abs: str, v: Validator) -> List[dict]:
    # Simplified: produce top-level entry and recurse keywords at top level only
    details = []
    errors: List[ValidationError] = []
    v.validate(schema, instance, "", "", errors)
    is_valid = not errors
    top = {
        "evaluationPath": "",
        "instanceLocation": "",
        "schemaLocation": f"file://{schema_abs}#",
        "valid": is_valid,
    }
    if not is_valid and isinstance(schema, bool) and schema is False:
        top["errors"] = {"falseSchema": f"False schema does not allow {format_value(instance)}"}
    details.append(top)
    return details


def build_hierarchical(schema: Any, instance: Any, schema_abs: str, v: Validator,
                        schema_path: str, inst_path: str, eval_path: str) -> dict:
    errors: List[ValidationError] = []
    v.validate(schema, instance, "", "", errors)
    is_valid = not errors
    out = {
        "evaluationPath": eval_path,
        "instanceLocation": inst_path,
        "schemaLocation": f"file://{schema_abs}#{schema_path}",
        "valid": is_valid,
    }
    if not is_valid and isinstance(schema, bool) and schema is False:
        out["errors"] = {"falseSchema": f"False schema does not allow {format_value(instance)}"}
    return out


if __name__ == "__main__":
    sys.exit(main())
