        else:
            sys.stderr.write("Usage: executable <SCHEMA>\n\n")
        sys.stderr.write("For more information, try '--help'.\n")
        sys.exit(2)
    return args


def possible_values_hint(attr: str) -> str:
    if attr == "draft":
        return "\n  [possible values: 4, 6, 7, 2019, 2020]"
    if attr == "output":
        return "\n  [possible values: text, flag, list, hierarchical]"
    return ""


# ---------- JSON helpers ----------

def canon_json(obj: Any) -> str:
    """JSON encoding matching serde_json: compact, sorted? No, serde preserves order.
    However for error messages some items (like instance) are compact, order-preserving.
    For uniqueness comparisons we need canonical form."""
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"))


def canon_sorted(obj: Any) -> str:
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"), sort_keys=True)


def format_value(value: Any) -> str:
    """Format a value for user-facing messages (e.g., `"str"`, `5`, `[1,2,3]`)."""
    return canon_json(value)


def json_equal(a: Any, b: Any) -> bool:
    """JSON-equal: numbers 1 == 1.0, but true != 1."""
    if isinstance(a, bool) or isinstance(b, bool):
        if isinstance(a, bool) and isinstance(b, bool):
            return a == b
        return False
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return float(a) == float(b)
    if type(a) is not type(b):
        return False
    if isinstance(a, list):
        if len(a) != len(b):
            return False
        return all(json_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(json_equal(a[k], b[k]) for k in a)
    return a == b


# ---------- Numeric helpers ----------

def is_number(v: Any) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def is_integer(v: Any) -> bool:
    if isinstance(v, bool):
        return False
    if isinstance(v, int):
        return True
    if isinstance(v, float):
        return v.is_integer()
    return False


def type_of(v: Any) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, int):
        return "integer"
    if isinstance(v, float):
        return "integer" if v.is_integer() else "number"
    if isinstance(v, str):
        return "string"
    if isinstance(v, list):
        return "array"
    if isinstance(v, dict):
        return "object"
    return "unknown"


# ---------- Validation errors ----------

class ValidationError(Exception):
    def __init__(self, message: str, keyword: str, evaluation_path: str, instance_path: str):
        self.message = message
        self.keyword = keyword
        self.evaluation_path = evaluation_path
        self.instance_path = instance_path


def escape_pointer(segment: str) -> str:
    return segment.replace("~", "~0").replace("/", "~1")


# ---------- Schema Draft detection ----------

def detect_draft(schema: Any, forced: Optional[str]) -> str:
    if forced is not None:
        return {"4": "4", "6": "6", "7": "7", "2019": "2019", "2020": "2020"}[forced]
    if isinstance(schema, dict):
        sch = schema.get("$schema")
        if isinstance(sch, str):
            if "draft-04" in sch:
                return "4"
            if "draft-06" in sch:
                return "6"
            if "draft-07" in sch:
                return "7"
            if "2019-09" in sch:
                return "2019"
            if "2020-12" in sch:
                return "2020"
    return "2020"


# ---------- The validator ----------

class Validator:
    def __init__(self, root: Any, draft: str, assert_format: bool):
        self.root = root
        self.draft = draft
        self.assert_format = assert_format

    def resolve_ref(self, ref: str) -> Any:
        if not ref.startswith("#"):
            return None
        frag = ref[1:]
        if frag.startswith("/"):
            parts = frag.split("/")[1:]
        elif frag == "":
            return self.root
        else:
            return None
        node = self.root
        for p in parts:
            p = p.replace("~1", "/").replace("~0", "~")
            try:
                # url-decode percent sequences
                p = re.sub(r"%([0-9A-Fa-f]{2})", lambda m: chr(int(m.group(1), 16)), p)
            except Exception:
                pass
            if isinstance(node, dict) and p in node:
                node = node[p]
            elif isinstance(node, list):
                try:
                    node = node[int(p)]
                except Exception:
                    return None
            else:
                return None
        return node

    def validate(
        self,
        schema: Any,
        instance: Any,
        schema_path: str,
        inst_path: str,
        errors: List[ValidationError],
    ) -> None:
        if schema is True or schema == {}:
            return
        if schema is False:
            errors.append(ValidationError(
                f"False schema does not allow {format_value(instance)}",
                "falseSchema", schema_path, inst_path,
            ))
            return
        if not isinstance(schema, dict):
            return
        # $ref
        if "$ref" in schema and isinstance(schema["$ref"], str):
            target = self.resolve_ref(schema["$ref"])
            if target is not None:
                self.validate(target, instance, schema_path + "/$ref", inst_path, errors)
                # draft 2019+ allows sibling keywords; draft 7 ignores them
                if self.draft in ("4", "6", "7"):
                    return
        # type
        if "type" in schema:
            t = schema["type"]
            ts = t if isinstance(t, list) else [t]
            if not any(self._type_matches(ti, instance) for ti in ts):
                if isinstance(t, list):
                    sorted_ts = ", ".join(f'"{x}"' for x in sorted(ts))
                    errors.append(ValidationError(
                        f"{format_value(instance)} is not of types {sorted_ts}",
                        "type", schema_path + "/type", inst_path,
                    ))
                else:
                    errors.append(ValidationError(
                        f"{format_value(instance)} is not of type \"{t}\"",
                        "type", schema_path + "/type", inst_path,
                    ))

        # enum
        if "enum" in schema:
            enum_values = schema["enum"]
            if not any(json_equal(instance, ev) for ev in enum_values):
                if len(enum_values) == 1:
                    msg = f"{format_value(instance)} is not one of {format_value(enum_values[0])}"
                elif len(enum_values) == 2:
                    msg = (
                        f"{format_value(instance)} is not one of "
                        f"{format_value(enum_values[0])} or {format_value(enum_values[1])}"
                    )
                else:
                    rest = len(enum_values) - 2
                    msg = (
                        f"{format_value(instance)} is not one of "
                        f"{format_value(enum_values[0])}, {format_value(enum_values[1])} or {rest} other candidates"
                    )
                errors.append(ValidationError(
                    msg, "enum", schema_path + "/enum", inst_path,
                ))

        # const
        if "const" in schema:
            if not json_equal(instance, schema["const"]):
                errors.append(ValidationError(
                    f"{format_value(schema['const'])} was expected",
                    "const", schema_path + "/const", inst_path,
                ))

        # allOf
        if "allOf" in schema and isinstance(schema["allOf"], list):
            for i, sub in enumerate(schema["allOf"]):
                self.validate(sub, instance, f"{schema_path}/allOf/{i}", inst_path, errors)
        # anyOf
        if "anyOf" in schema and isinstance(schema["anyOf"], list):
            any_ok = False
            for sub in schema["anyOf"]:
                sub_errors: List[ValidationError] = []
                self.validate(sub, instance, "", inst_path, sub_errors)
                if not sub_errors:
                    any_ok = True
                    break
            if not any_ok:
                errors.append(ValidationError(
                    f"{format_value(instance)} is not valid under any of the schemas listed in the 'anyOf' keyword",
                    "anyOf", schema_path + "/anyOf", inst_path,
                ))
        # oneOf
        if "oneOf" in schema and isinstance(schema["oneOf"], list):
            ok_count = 0
            for sub in schema["oneOf"]:
                sub_errors: List[ValidationError] = []
                self.validate(sub, instance, "", inst_path, sub_errors)
                if not sub_errors:
                    ok_count += 1
                    if ok_count > 1:
                        break
            if ok_count == 0:
                errors.append(ValidationError(
                    f"{format_value(instance)} is not valid under any of the schemas listed in the 'oneOf' keyword",
                    "oneOf", schema_path + "/oneOf", inst_path,
                ))
            elif ok_count > 1:
                errors.append(ValidationError(
                    f"{format_value(instance)} is valid under more than one of the schemas listed in the 'oneOf' keyword",
                    "oneOf", schema_path + "/oneOf", inst_path,
                ))
        # not
        if "not" in schema:
            sub_errors: List[ValidationError] = []
            self.validate(schema["not"], instance, "", inst_path, sub_errors)
            if not sub_errors:
                errors.append(ValidationError(
                    f"{format_value(schema['not'])} is not allowed for {format_value(instance)}",
                    "not", schema_path + "/not", inst_path,
                ))

        # numeric constraints
        if is_number(instance):
            if "minimum" in schema:
                m = schema["minimum"]
                if is_number(m):
                    if instance < m:
                        errors.append(ValidationError(
                            f"{format_value(instance)} is less than the minimum of {format_value(m)}",
                            "minimum", schema_path + "/minimum", inst_path,
                        ))
            if "maximum" in schema:
                m = schema["maximum"]
                if is_number(m):
                    if instance > m:
                        errors.append(ValidationError(
                            f"{format_value(instance)} is greater than the maximum of {format_value(m)}",
                            "maximum", schema_path + "/maximum", inst_path,
                        ))
            if "exclusiveMinimum" in schema:
                m = schema["exclusiveMinimum"]
                if is_number(m):
                    if instance <= m:
                        errors.append(ValidationError(
                            f"{format_value(instance)} is less than or equal to the minimum of {format_value(m)}",
                            "exclusiveMinimum", schema_path + "/exclusiveMinimum", inst_path,
                        ))
            if "exclusiveMaximum" in schema:
                m = schema["exclusiveMaximum"]
                if is_number(m):
                    if instance >= m:
                        errors.append(ValidationError(
                            f"{format_value(instance)} is greater than or equal to the maximum of {format_value(m)}",
                            "exclusiveMaximum", schema_path + "/exclusiveMaximum", inst_path,
                        ))
            if "multipleOf" in schema:
                mo = schema["multipleOf"]
                if is_number(mo) and mo > 0:
                    q = instance / mo
                    if abs(q - round(q)) > 1e-12:
                        errors.append(ValidationError(
                            f"{format_value(instance)} is not a multiple of {format_value(mo)}",
                            "multipleOf", schema_path + "/multipleOf", inst_path,
                        ))

